def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        use_count = {}
        def wrapper(*args, **kwargs):
            if typed:
                key = args + tuple(kwargs.items())
            else:
                key = args
            if key in cache:
                use_count[key] += 1
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result
                use_count[key] = 1
                if len(cache) > maxsize:
                    for k, v in sorted(use_count.items(), key=lambda x: x[1]):
                        if k in cache:
                            del cache[k]
                            del use_count[k]
                            break
                return result
        return wrapper
    return decorator
