def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Sort the classes by their MRO (Method Resolution Order)
    sorted_classes = sorted(classes, key=lambda cls: cls.__mro__)

    # Create a set to store the minimal bases
    minimal_bases = set()

    # Iterate over the sorted classes
    for cls in sorted_classes:
        # If the class is not a subclass of any of the existing minimal bases, add it to the set
        if not any(issubclass(cls, base) for base in minimal_bases):
            minimal_bases.add(cls)

    # Return the minimal bases as a list
    return list(minimal_bases)

