def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for i in range(len(observer_schema)):
        if isinstance(observer_schema[i], list):
            if i >= len(last_applied_manifest):
                last_applied_manifest.append([])
            update_last_applied_manifest_list_from_resp(last_applied_manifest[i], observer_schema[i], response[i])
        else:
            if i >= len(last_applied_manifest):
                last_applied_manifest.append(None)
            if last_applied_manifest[i] is None:
                last_applied_manifest[i] = response[i]
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema:
        if field not in response:
            raise KeyError(f"Observed field {field} not present in Kubernetes response")
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
        if isinstance(response[field], dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
        elif isinstance(response[field], list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[field], observer_schema[field], response[field])

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for i, item in enumerate(response):
        if i >= len(last_applied_manifest):
            last_applied_manifest.append(item)
        if isinstance(item, dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[i], observer_schema, item)
        elif isinstance(item, list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[i], observer_schema, item)

def update_last_applied_manifest_from_resp(last_applied_manifest, observer_schema, response):
