def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check that prior is an InventoryValidator object
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")

    # Check that self and prior inventories are consistent
    if not self.is_consistent() or not prior.is_consistent():
        raise ValueError("self and prior inventories must be consistent")

    # Check that prior is a prior version of self
    if not self.is_prior_version(prior):
        raise ValueError("prior is not a prior version of self")

    # Check that prior has no new or modified items
    for item in prior.items:
        if item not in self.items:
            raise ValueError("prior has new or modified items")

    # Check that prior has no new or modified categories
    for category in prior.categories:
        if category not in self.categories:
            raise ValueError("prior has new or modified categories")

    # Check that prior has no new or modified subcategories
    for subcategory in prior.subcategories:
        if subcategory not in self.subcategories:
            raise ValueError("prior has new or modified subcategories")

    # Check that prior has no new or modified items in any category
    for category in prior.categories:
        for item in prior.items:
            if item.category == category and item not in self.items:
                raise ValueError("prior has new or modified items in category " + category)

    # Check that prior has no new or modified items in any subcategory
    for subcategory in prior.subcategories:
        for item in prior.items:
            if item.subcategory == subcategory and item not in self.items:
                raise ValueError("prior has new or modified items in subcategory " + subcategory)

    # Check that prior has no new or modified items with the same name
    for item in prior.items:
        if item.name in self.items:
            raise ValueError("prior has new or modified items with the same name")

    # Check that prior has no new or modified items with the same category and subcategory
    for item in prior.items:
        if item.category == self.items[item.name].category and item.subcategory == self.items[item.name].subcategory:
            raise ValueError("prior has new or modified items with the same category and subcategory")

    # Check that prior has no new or modified items with the same name and category
    for item in prior.items:
        if item.name == self.items[item.name].name and item.category == self.items[item.name].category:
            raise ValueError("prior has new or modified items with the same name and category")

    # Check that prior has no new or modified items with the same name and subcategory
    for item in prior.items:
        if item.name == self.items[item.name].name and item.subcategory == self.items[item.name].subcategory:
            raise ValueError("prior has new or modified items with the same name and subcategory")

    # Check that prior has no new or modified items with the same category and subcategory and name
    for item in prior.items:
        if item.category == self.items[item.name].category and item.subcategory == self.items[item.name].subcategory and item.name == self.items[item.name].name:
            raise ValueError("prior has new or modified items with the same category, subcategory, and name")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for file in inventory.files:
        if file.version == version:
            logical_path_map[file.logical_path] = set()
        elif file.logical_path in logical_path_map:
            logical_path_map[file.logical_path].add(file)
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check that fixity is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Check that fixity has a 'fixity_algorithm' key
    if 'fixity_algorithm' not in fixity:
        raise ValueError("Fixity block must have a 'fixity_algorithm' key")

    # Check that fixity has a 'fixity_value' key
    if 'fixity_value' not in fixity:
        raise ValueError("Fixity block must have a 'fixity_value' key")

    # Check that fixity has a 'fixity_source' key
    if 'fixity_source' not in fixity:
        raise ValueError("Fixity block must have a 'fixity_source' key")

    # Check that fixity_source is a list
    if not isinstance(fixity['fixity_source'], list):
        raise ValueError("Fixity source must be a list")

    # Check that all files in fixity_source are in manifest_files
    for file in fixity['fixity_source']:
        if file not in manifest_files:
            raise ValueError(f"File {file} in fixity source is not in manifest")

    # Check that fixity_value is a string
    if not isinstance(fixity['fixity_value'], str):
        raise ValueError("Fixity value must be a string")

    # Check that fixity_algorithm is a string
    if not isinstance(fixity['fixity_algorithm'], str):
        raise ValueError("Fixity algorithm must be a string")

