def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    from lxml import etree

    response = requests.get(handle)
    if response.status_code == 200:
        doc = etree.fromstring(response.content)
        webfinger = {}
        for link in doc.findall(".//{http://www.w3.org/2005/Atom}link"):
            if link.get("rel") == "http://schemas.google.com/g/2010#updates-from":
                webfinger["updates-from"] = link.get("href")
            elif link.get("rel") == "http://schemas.google.com/g/2010#updates-from":
                webfinger["updates-to"] = link.get("href")
        return webfinger
    else:
        raise Exception("Failed to retrieve webfinger document")

